script:
(function () {
  'use strict';

  var video = document.getElementById('cameraVideo');
  var previewWrap = document.getElementById('cameraPreviewWrap');
  var placeholder = document.getElementById('cameraPlaceholder');
  var deviceSelect = document.getElementById('deviceSelect');
  var btnStart = document.getElementById('btnStartCamera');
  var btnStop = document.getElementById('btnStopCamera');
  var btnMirror = document.getElementById('btnMirrorToggle');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var statResolution = document.getElementById('camStatResolution');
  var statFps = document.getElementById('camStatFps');
  var statFacing = document.getElementById('camStatFacing');
  var statDeviceName = document.getElementById('camStatDeviceName');
  var capabilitiesGrid = document.getElementById('capabilitiesGrid');
  var capZoom = document.getElementById('capZoom');
  var capTorch = document.getElementById('capTorch');
  var capFocus = document.getElementById('capFocus');

  var currentStream = null;
  var currentDeviceId = '';
  var starting = false;

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    // items: [{sev: 'ok'|'warn'|'error'|'', html: '...'}]
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  function resetInfo() {
    statResolution.textContent = '—';
    statFps.textContent = '—';
    statFacing.textContent = '—';
    statDeviceName.textContent = '—';
    capabilitiesGrid.style.display = 'none';
  }

  // Every camera page on this site copies this stopStream()/enumerate/error
  // pattern as its starting point (see this project's own CLAUDE.md — "no
  // shared JS runtime file" is a deliberate choice, so teardown discipline
  // has to be copied verbatim into every tool's own script instead of
  // living in one shared file). Calling stop() on every track here is the
  // single highest-stakes correctness requirement on this whole site: skip
  // it and the browser's camera indicator light stays on after the visitor
  // has left the page.
  function stopStream() {
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    video.srcObject = null;
    previewWrap.classList.remove('is-active');
    placeholder.style.display = 'flex';
    btnStop.disabled = true;
    btnMirror.disabled = true;
    resetInfo();
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Camera access was blocked.</strong> Click the camera icon in your address bar (or your browser’s site settings) and allow access, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No camera was detected.</strong> Make sure a webcam is connected, then reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your camera is already in use.</strong> Another app or browser tab is probably holding it — close video-calling apps or other camera tabs and try again.' };
      case 'OverconstrainedError':
      case 'ConstraintNotSatisfiedError':
        return { sev: 'error', html: '<strong>This camera doesn’t support the requested settings.</strong> Try a different camera from the list above.' };
      case 'SecurityError':
        return { sev: 'error', html: '<strong>Camera access requires a secure connection.</strong> Make sure this page is loaded over HTTPS.' };
      case 'AbortError':
        return { sev: 'warn', html: 'The camera request was interrupted. Click <strong>Start Camera</strong> to try again.' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong starting the camera.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function populateDeviceSelect(devices) {
    var cams = devices.filter(function (d) { return d.kind === 'videoinput'; });
    deviceSelect.innerHTML = '';
    if (!cams.length) {
      var opt = document.createElement('option');
      opt.value = '';
      opt.textContent = 'No cameras found';
      deviceSelect.appendChild(opt);
      deviceSelect.disabled = true;
      return;
    }
    cams.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Camera ' + (i + 1));
      if (d.deviceId === currentDeviceId) opt.selected = true;
      deviceSelect.appendChild(opt);
    });
    deviceSelect.disabled = false;
  }

  function refreshDeviceList() {
    if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) return Promise.resolve();
    return navigator.mediaDevices.enumerateDevices().then(populateDeviceSelect).catch(function () {});
  }

  function updateInfo(track) {
    var settings = track.getSettings ? track.getSettings() : {};
    statResolution.textContent = settings.width && settings.height ? (settings.width + '×' + settings.height) : '—';
    statFps.textContent = settings.frameRate ? (Math.round(settings.frameRate * 10) / 10 + ' fps') : '—';
    statFacing.textContent = settings.facingMode || 'Unspecified';
    statDeviceName.textContent = track.label || 'Camera';
  }

  // Capability flags (zoom/torch/focus) are only meaningful once the track's
  // constrainable-property range is known -- getCapabilities() is unsupported
  // in Firefox and Safari, so an unreported flag means 'browser doesn't expose
  // this', not 'camera doesn't have it'.
  function updateCapabilities(track) {
    if (!track.getCapabilities) {
      capZoom.textContent = capTorch.textContent = capFocus.textContent = 'Not reported';
      capabilitiesGrid.style.display = '';
      return;
    }
    var caps = track.getCapabilities();
    capZoom.textContent = caps.zoom ? ('Yes (' + caps.zoom.min + '\u2013' + caps.zoom.max + ')') : 'No';
    capTorch.textContent = caps.torch ? 'Yes' : 'No';
    capFocus.textContent = caps.focusMode && caps.focusMode.length ? caps.focusMode.join(', ') : 'No';
    capabilitiesGrid.style.display = '';
  }

  function startStream(deviceId) {
    if (starting) return;
    starting = true;
    // Always fully release the previous stream before requesting a new
    // one — requesting a second stream while the first is still active
    // leaves the camera locked at the earlier resolution/device on many
    // browsers.
    stopStream();
    setDiagnostic([{ sev: '', html: 'Requesting camera access…' }]);
    btnStart.disabled = true;

    var videoConstraint = deviceId ? { deviceId: { exact: deviceId } } : true;
    navigator.mediaDevices.getUserMedia({ video: videoConstraint, audio: false })
      .then(function (stream) {
        currentStream = stream;
        video.srcObject = stream;
        placeholder.style.display = 'none';
        previewWrap.classList.add('is-active');
        return video.play().catch(function () {}).then(function () { return stream; });
      })
      .then(function (stream) {
        var track = stream.getVideoTracks()[0];
        var settings = track.getSettings ? track.getSettings() : {};
        currentDeviceId = settings.deviceId || deviceId || '';
        updateInfo(track);
        updateCapabilities(track);
        btnStop.disabled = false;
        btnMirror.disabled = false;
        setDiagnostic([{ sev: 'ok', html: '<strong>Camera is live.</strong> Nothing is uploaded — this feed stays in your browser tab.' }]);
        return refreshDeviceList();
      })
      .catch(function (err) {
        setDiagnostic([describeError(err)]);
      })
      .finally(function () {
        starting = false;
        btnStart.disabled = false;
      });
  }

  btnStart.addEventListener('click', function () { startStream(deviceSelect.value); });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Camera stopped. Click <strong>Start Camera</strong> to test again.' }]);
  });
  btnMirror.addEventListener('click', function () {
    var mirrored = previewWrap.classList.toggle('is-mirrored');
    btnMirror.setAttribute('aria-pressed', mirrored ? 'true' : 'false');
    btnMirror.classList.toggle('active', mirrored);
  });
  deviceSelect.addEventListener('change', function () {
    if (currentStream) startStream(deviceSelect.value);
  });

  // Guaranteed teardown: release the camera the moment the visitor leaves
  // this page, even if they never clicked Stop. pagehide covers back-
  // forward-cache navigations that 'unload' can miss.
  window.addEventListener('pagehide', stopStream);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support camera access.</strong> Try the latest version of Chrome, Firefox, Edge, or Safari.' }]);
    btnStart.disabled = true;
  }
})();

(function () {
  'use strict';

  var video = document.getElementById('cameraVideo');
  var previewWrap = document.getElementById('cameraPreviewWrap');
  var placeholder = document.getElementById('cameraPlaceholder');
  var canvas = document.getElementById('captureCanvas');
  var deviceSelect = document.getElementById('deviceSelect');
  var btnStart = document.getElementById('btnStartCamera');
  var btnStop = document.getElementById('btnStopCamera');
  var btnCapture = document.getElementById('btnCaptureFrame');
  var btnCopy = document.getElementById('btnCopyReport');
  var btnDownload = document.getElementById('btnDownloadReport');
  var diagnosticPanel = document.getElementById('diagnosticPanel');

  var ids = ['DeviceName', 'Resolution', 'Megapixels', 'AspectRatio', 'FrameRate', 'FacingMode', 'FocusMode', 'ResolutionRange', 'FrameRateRange', 'DeviceId', 'Brightness', 'Saturation', 'Hue', 'Rgb', 'ColourCount'];
  var fields = {};
  ids.forEach(function (id) { fields[id] = document.getElementById('info' + id); });

  var currentStream = null;
  var starting = false;
  var lastReport = null;

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  function setField(id, value, unsupported) {
    var el = fields[id];
    if (!el) return;
    el.textContent = value;
    el.classList.toggle('unsupported', !!unsupported);
  }

  function gcd(a, b) { return b === 0 ? a : gcd(b, a % b); }

  function resetHardwareFields() {
    ids.slice(0, 10).forEach(function (id) { setField(id, '—'); });
  }
  function resetImageFields() {
    ids.slice(10).forEach(function (id) { setField(id, '—'); });
  }

  // Same stopStream()/enumerate/error pattern as webcam-test-online's own
  // script (see this project's CLAUDE.md — every camera tool copies this
  // teardown block rather than importing a shared file).
  function stopStream() {
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    video.srcObject = null;
    previewWrap.classList.remove('is-active');
    placeholder.style.display = 'flex';
    btnStop.disabled = true;
    btnCapture.disabled = true;
    resetHardwareFields();
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Camera access was blocked.</strong> Allow access from your browser’s address-bar icon or site settings, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No camera was detected.</strong> Connect a webcam and reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your camera is already in use</strong> by another app or browser tab.' };
      case 'OverconstrainedError':
      case 'ConstraintNotSatisfiedError':
        return { sev: 'error', html: '<strong>This camera doesn’t support the requested settings.</strong> Try another camera from the list.' };
      case 'SecurityError':
        return { sev: 'error', html: '<strong>Camera access requires HTTPS.</strong>' };
      case 'AbortError':
        return { sev: 'warn', html: 'The camera request was interrupted. Click <strong>Start Camera</strong> to try again.' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong starting the camera.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function populateDeviceSelect(devices, currentDeviceId) {
    var cams = devices.filter(function (d) { return d.kind === 'videoinput'; });
    deviceSelect.innerHTML = '';
    if (!cams.length) {
      var noneOpt = document.createElement('option');
      noneOpt.value = '';
      noneOpt.textContent = 'No cameras found';
      deviceSelect.appendChild(noneOpt);
      deviceSelect.disabled = true;
      return;
    }
    cams.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Camera ' + (i + 1));
      if (d.deviceId === currentDeviceId) opt.selected = true;
      deviceSelect.appendChild(opt);
    });
    deviceSelect.disabled = false;
  }

  function fillHardwareReport(track) {
    var settings = track.getSettings ? track.getSettings() : {};
    var caps = track.getCapabilities ? (function () { try { return track.getCapabilities(); } catch (e) { return null; } })() : null;

    setField('DeviceName', track.label || 'Camera');
    if (settings.width && settings.height) {
      setField('Resolution', settings.width + '×' + settings.height);
      var mp = (settings.width * settings.height / 1e6).toFixed(2) + ' MP';
      setField('Megapixels', mp);
      var g = gcd(settings.width, settings.height) || 1;
      setField('AspectRatio', (settings.width / g) + ':' + (settings.height / g));
    } else {
      setField('Resolution', 'Not reported', true);
      setField('Megapixels', 'Not reported', true);
      setField('AspectRatio', 'Not reported', true);
    }
    setField('FrameRate', settings.frameRate ? (Math.round(settings.frameRate * 10) / 10 + ' fps') : 'Not reported', !settings.frameRate);
    setField('FacingMode', settings.facingMode || 'Not reported', !settings.facingMode);

    if (caps) {
      setField('FocusMode', (caps.focusMode && caps.focusMode.length) ? caps.focusMode.join(', ') : 'Not reported', !(caps.focusMode && caps.focusMode.length));
      if (caps.width && caps.height) {
        setField('ResolutionRange', caps.width.min + '×' + caps.height.min + ' – ' + caps.width.max + '×' + caps.height.max);
      } else {
        setField('ResolutionRange', 'Not reported', true);
      }
      if (caps.frameRate) {
        setField('FrameRateRange', (Math.round(caps.frameRate.min * 10) / 10) + ' – ' + (Math.round(caps.frameRate.max * 10) / 10) + ' fps');
      } else {
        setField('FrameRateRange', 'Not reported', true);
      }
    } else {
      // Firefox doesn't implement getCapabilities() at all -- degrade
      // gracefully rather than treating this as a failure (per this
      // project's spec: "design for partial data").
      setField('FocusMode', 'Unsupported in this browser', true);
      setField('ResolutionRange', 'Unsupported in this browser', true);
      setField('FrameRateRange', 'Unsupported in this browser', true);
    }
    setField('DeviceId', settings.deviceId || 'Not reported', !settings.deviceId);
  }

  function startStream(deviceId) {
    if (starting) return;
    starting = true;
    stopStream();
    setDiagnostic([{ sev: '', html: 'Requesting camera access…' }]);
    btnStart.disabled = true;

    navigator.mediaDevices.getUserMedia({ video: deviceId ? { deviceId: { exact: deviceId } } : true, audio: false })
      .then(function (stream) {
        currentStream = stream;
        video.srcObject = stream;
        placeholder.style.display = 'none';
        previewWrap.classList.add('is-active');
        return video.play().catch(function () {}).then(function () { return stream; });
      })
      .then(function (stream) {
        var track = stream.getVideoTracks()[0];
        fillHardwareReport(track);
        btnStop.disabled = false;
        btnCapture.disabled = false;
        setDiagnostic([{ sev: 'ok', html: '<strong>Camera is live.</strong> Click <strong>Analyse a Frame</strong> to fill in the image metrics below.' }]);
        var settings = track.getSettings ? track.getSettings() : {};
        return navigator.mediaDevices.enumerateDevices().then(function (devices) {
          populateDeviceSelect(devices, settings.deviceId);
        });
      })
      .catch(function (err) { setDiagnostic([describeError(err)]); })
      .finally(function () { starting = false; btnStart.disabled = false; });
  }

  function analyseFrame() {
    if (!currentStream) return;
    var track = currentStream.getVideoTracks()[0];
    var settings = track.getSettings ? track.getSettings() : {};
    var w = settings.width || video.videoWidth;
    var h = settings.height || video.videoHeight;
    if (!w || !h) return;

    // Downsample before analysing -- a full 4K frame's pixel loop would be
    // slow and the extra resolution adds nothing to an average-colour /
    // brightness estimate. 160px on the long edge is plenty.
    var scale = Math.min(1, 160 / Math.max(w, h));
    var sw = Math.max(1, Math.round(w * scale));
    var sh = Math.max(1, Math.round(h * scale));
    canvas.width = sw;
    canvas.height = sh;
    var ctx = canvas.getContext('2d');
    ctx.drawImage(video, 0, 0, sw, sh);

    try {
      var data = ctx.getImageData(0, 0, sw, sh).data;
      var rSum = 0, gSum = 0, bSum = 0, count = 0;
      var seen = new Set();
      var hueSum = 0, satSum = 0, briSum = 0;
      for (var i = 0; i < data.length; i += 4) {
        var r = data[i], g = data[i + 1], b = data[i + 2];
        rSum += r; gSum += g; bSum += b; count++;
        seen.add((r >> 4) + ',' + (g >> 4) + ',' + (b >> 4));
        var max = Math.max(r, g, b), min = Math.min(r, g, b);
        var l = (max + min) / 2 / 255;
        briSum += l;
        var s = max === min ? 0 : (l > 0.5 ? (max - min) / (2 - max / 255 - min / 255) / 255 : (max - min) / (max + min));
        satSum += s;
        var hh = 0;
        if (max !== min) {
          var d = max - min;
          if (max === r) hh = ((g - b) / d + (g < b ? 6 : 0));
          else if (max === g) hh = (b - r) / d + 2;
          else hh = (r - g) / d + 4;
          hh *= 60;
        }
        hueSum += hh;
      }
      var avgR = Math.round(rSum / count), avgG = Math.round(gSum / count), avgB = Math.round(bSum / count);
      setField('Brightness', Math.round((briSum / count) * 100) + '%');
      setField('Saturation', Math.round((satSum / count) * 100) + '%');
      setField('Hue', Math.round(hueSum / count) + '°');
      setField('Rgb', 'rgb(' + avgR + ', ' + avgG + ', ' + avgB + ')');
      setField('ColourCount', seen.size.toLocaleString() + ' (of ' + count.toLocaleString() + ' px sampled)');
      setDiagnostic([{ sev: 'ok', html: '<strong>Frame analysed.</strong> Image metrics below are from this single captured frame — recapture any time for a fresh reading.' }]);
    } catch (e) {
      setDiagnostic([{ sev: 'warn', html: 'Could not read pixel data from this frame: ' + escapeHtml(e.message || 'unknown error') + '.' }]);
    }
  }

  function buildReportObject() {
    var report = {};
    ids.forEach(function (id) { report[id] = fields[id].textContent; });
    return report;
  }

  function reportAsText(report) {
    var labels = {
      DeviceName: 'Device Name', Resolution: 'Resolution', Megapixels: 'Megapixels', AspectRatio: 'Aspect Ratio',
      FrameRate: 'Frame Rate', FacingMode: 'Facing Mode', FocusMode: 'Focus Mode', ResolutionRange: 'Resolution Range',
      FrameRateRange: 'Frame Rate Range', DeviceId: 'Device ID', Brightness: 'Average Brightness',
      Saturation: 'Average Saturation', Hue: 'Average Hue', Rgb: 'Average RGB', ColourCount: 'Distinct Colours Sampled',
    };
    return 'WebcamTest Camera Information Report\n' + ids.map(function (id) { return labels[id] + ': ' + report[id]; }).join('\n');
  }

  btnStart.addEventListener('click', function () { startStream(deviceSelect.value); });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Camera stopped.' }]);
  });
  btnCapture.addEventListener('click', analyseFrame);
  deviceSelect.addEventListener('change', function () { if (currentStream) startStream(deviceSelect.value); });

  btnCopy.addEventListener('click', function () {
    var text = reportAsText(buildReportObject());
    (navigator.clipboard ? navigator.clipboard.writeText(text) : Promise.reject())
      .then(function () {
        var original = btnCopy.textContent;
        btnCopy.textContent = 'Copied!';
        setTimeout(function () { btnCopy.innerHTML = btnCopy.dataset.original || original; }, 1500);
      })
      .catch(function () {});
  });
  btnCopy.dataset.original = btnCopy.innerHTML;

  btnDownload.addEventListener('click', function () {
    var report = buildReportObject();
    var blob = new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = 'camera-information-report.json';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
  });

  window.addEventListener('pagehide', stopStream);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support camera access.</strong>' }]);
    btnStart.disabled = true;
  }
})();

(function () {
  'use strict';

  var video = document.getElementById('cameraVideo');
  var previewWrap = document.getElementById('cameraPreviewWrap');
  var placeholder = document.getElementById('cameraPlaceholder');
  var deviceSelect = document.getElementById('deviceSelect');
  var btnDetect = document.getElementById('btnDetect');
  var btnStop = document.getElementById('btnStopCamera');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var progressWrap = document.getElementById('probeProgressWrap');
  var progressFill = document.getElementById('probeProgressFill');
  var ladderList = document.getElementById('ladderList');
  var statResolution = document.getElementById('statPeakResolution');
  var statMegapixels = document.getElementById('statPeakMegapixels');
  var statAspect = document.getElementById('statPeakAspect');
  var statStandard = document.getElementById('statPeakStandard');

  // Standard video resolutions, 8K down to QQVGA, sorted by pixel area
  // descending. Kept as the single source the ladder display and the probe
  // loop both read from, so they can never disagree with each other.
  var STANDARDS = [
    ['8K UHD', 7680, 4320], ['5K', 5120, 2880], ['DCI 4K', 4096, 2160], ['4K UHD', 3840, 2160],
    ['QHD+', 2560, 1600], ['QHD', 2560, 1440], ['Full HD+', 1920, 1200], ['Full HD', 1920, 1080],
    ['HD+', 1600, 900], ['HD', 1280, 720], ['XGA', 1024, 768], ['WSVGA', 1024, 600],
    ['SVGA', 800, 600], ['VGA', 640, 480], ['CIF', 352, 288], ['QVGA', 320, 240],
    ['QCIF', 176, 144], ['QQVGA', 160, 120],
  ].sort(function (a, b) { return (b[1] * b[2]) - (a[1] * a[2]); });

  var currentStream = null;
  var running = false;

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  function gcd(a, b) { return b === 0 ? a : gcd(b, a % b); }

  function renderLadder(peakArea, activeName) {
    ladderList.innerHTML = STANDARDS.map(function (s) {
      var name = s[0], w = s[1], h = s[2];
      var area = w * h;
      var cls = 'ladder-item';
      if (peakArea !== null) {
        if (area <= peakArea) cls += ' supported';
        if (name === activeName) cls += ' best';
      }
      var status = peakArea === null ? '' : (area <= peakArea ? (name === activeName ? 'Best match' : 'Reachable') : 'Not reached');
      return '<div class="' + cls + '"><span class="ladder-name">' + escapeHtml(name) + '</span>' +
        '<span class="ladder-dims">' + w + '×' + h + '</span><span>' + status + '</span></div>';
    }).join('');
  }

  // Same stopStream() shape every camera tool on this site copies (see
  // webcam-test-online's own script and this project's CLAUDE.md).
  function stopStream() {
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    video.srcObject = null;
    previewWrap.classList.remove('is-active');
    placeholder.style.display = 'flex';
    btnStop.disabled = true;
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Camera access was blocked.</strong> Allow access from your browser’s address-bar icon or site settings, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No camera was detected.</strong> Connect a webcam and reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your camera is already in use</strong> by another app or browser tab.' };
      case 'SecurityError':
        return { sev: 'error', html: '<strong>Camera access requires HTTPS.</strong>' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong probing the camera.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function populateDeviceSelect(devices, currentDeviceId) {
    var cams = devices.filter(function (d) { return d.kind === 'videoinput'; });
    deviceSelect.innerHTML = '';
    cams.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Camera ' + (i + 1));
      if (d.deviceId === currentDeviceId) opt.selected = true;
      deviceSelect.appendChild(opt);
    });
    deviceSelect.disabled = cams.length === 0;
  }

  function requestResolution(deviceId, w, h) {
    var videoConstraint = { width: { ideal: w }, height: { ideal: h } };
    if (deviceId) videoConstraint.deviceId = { exact: deviceId };
    return navigator.mediaDevices.getUserMedia({ video: videoConstraint, audio: false });
  }

  function runProbe(deviceId) {
    if (running) return;
    running = true;
    btnDetect.disabled = true;
    progressWrap.style.display = 'block';
    progressFill.style.width = '0%';
    renderLadder(null, null);
    setDiagnostic([{ sev: '', html: 'Probing resolutions — this briefly restarts the camera several times…' }]);

    var i = 0;
    var found = null; // { area, width, height }

    function next() {
      if (i >= STANDARDS.length) return finish();
      var entry = STANDARDS[i];
      progressFill.style.width = Math.round((i / STANDARDS.length) * 100) + '%';

      // Fully release the previous probe stream before requesting the
      // next -- a still-active stream leaves the camera locked at the
      // earlier resolution on many browsers/drivers.
      if (currentStream) {
        currentStream.getTracks().forEach(function (t) { t.stop(); });
        currentStream = null;
      }

      requestResolution(deviceId, entry[1], entry[2])
        .then(function (stream) {
          currentStream = stream;
          video.srcObject = stream;
          placeholder.style.display = 'none';
          previewWrap.classList.add('is-active');
          var track = stream.getVideoTracks()[0];
          var settings = track.getSettings ? track.getSettings() : {};
          var actualW = settings.width || 0, actualH = settings.height || 0;
          var actualArea = actualW * actualH;
          var wantArea = entry[1] * entry[2];

          if (!found && actualArea >= wantArea * 0.95) {
            // First (largest) standard mode this browser could actually
            // reach -- "stop at the first match" per this tool's spec.
            // Use the browser's own reported dimensions (actual), which
            // may exceed the named standard slightly.
            found = { area: actualArea, width: actualW, height: actualH, name: entry[0] };
            btnStop.disabled = false;
            return finish();
          }
          i++;
          next();
        })
        .catch(function (err) {
          // OverconstrainedError at the very top of the ladder is
          // expected on most cameras (nobody has an 8K webcam) -- treat
          // it as "not reached" and keep descending rather than aborting
          // the whole probe.
          if (err && (err.name === 'OverconstrainedError' || err.name === 'ConstraintNotSatisfiedError')) {
            i++;
            next();
            return;
          }
          running = false;
          btnDetect.disabled = false;
          progressWrap.style.display = 'none';
          setDiagnostic([describeError(err)]);
        });
    }

    function finish() {
      running = false;
      btnDetect.disabled = false;
      progressFill.style.width = '100%';
      setTimeout(function () { progressWrap.style.display = 'none'; }, 400);

      if (!found) {
        // The final probe attempt's stream is still live at this point (next()
        // only releases the *previous* stream before requesting the next one) --
        // release it now rather than leaving it dangling on the pagehide/
        // visibilitychange safety net.
        stopStream();
        setDiagnostic([{ sev: 'error', html: 'Could not negotiate any standard resolution with this camera.' }]);
        return;
      }

      var g = gcd(found.width, found.height) || 1;
      statResolution.textContent = found.width + '×' + found.height;
      statMegapixels.textContent = (found.width * found.height / 1e6).toFixed(2) + ' MP';
      statAspect.textContent = (found.width / g) + ':' + (found.height / g);
      statStandard.textContent = found.name;
      renderLadder(found.area, found.name);
      setDiagnostic([{ sev: 'ok', html: '<strong>' + found.width + '×' + found.height + '</strong> is the highest resolution your browser could negotiate with this camera. Your camera’s native sensor resolution — and what its own manufacturer app can reach — may be higher; browsers commonly cap out around 1080p or 4K regardless of the physical sensor.' }]);

      navigator.mediaDevices.enumerateDevices().then(function (devices) {
        var settings = currentStream ? currentStream.getVideoTracks()[0].getSettings() : {};
        populateDeviceSelect(devices, settings.deviceId);
      }).catch(function () {});
    }

    next();
  }

  btnDetect.addEventListener('click', function () { runProbe(deviceSelect.value); });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Camera stopped.' }]);
  });
  deviceSelect.addEventListener('change', function () {
    // Switching devices mid-result just clears the stale result rather
    // than auto-re-probing, since the probe is an intentionally heavier
    // action (several getUserMedia calls in a row).
    stopStream();
    statResolution.textContent = statMegapixels.textContent = statAspect.textContent = statStandard.textContent = '—';
    renderLadder(null, null);
    setDiagnostic([{ sev: '', html: 'Click <strong>Detect Maximum Resolution</strong> to probe this camera.' }]);
  });

  window.addEventListener('pagehide', stopStream);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  renderLadder(null, null);

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support camera access.</strong>' }]);
    btnDetect.disabled = true;
  }
})();

