      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Camera ' + (i + 1));
      if (d.deviceId === currentDeviceId) opt.selected = true;
      deviceSelect.appendChild(opt);
    });
    deviceSelect.disabled = cams.length === 0;
  }

  function startStream(deviceId) {
    if (starting) return;
    starting = true;
    stopStream();
    setDiagnostic([{ sev: '', html: 'Requesting camera access…' }]);
    btnStart.disabled = true;

    navigator.mediaDevices.getUserMedia({ video: deviceId ? { deviceId: { exact: deviceId } } : true, audio: false })
      .then(function (stream) {
        currentStream = stream;
        video.srcObject = stream;
        placeholder.style.display = 'none';
        previewWrap.classList.add('is-active');
        return video.play().catch(function () {}).then(function () { return stream; });
      })
      .then(function (stream) {
        var track = stream.getVideoTracks()[0];
        var settings = track.getSettings ? track.getSettings() : {};
        btnStop.disabled = false;
        setDiagnostic([{ sev: 'ok', html: '<strong>Camera is live.</strong> Use Next to move through the checklist.' }]);
        results.lens = 'pass';
        renderChecklist();
        renderStep();
        return navigator.mediaDevices.enumerateDevices().then(function (devices) {
          populateDeviceSelect(devices, settings.deviceId);
        });
      })
      .catch(function (err) {
        setDiagnostic([describeError(err)]);
        results.lens = 'fail';
        renderChecklist();
        stopStream();
      })
      .finally(function () { starting = false; btnStart.disabled = false; });
  }

  function currentTrack() {
    return currentStream ? currentStream.getVideoTracks()[0] : null;
  }

  function renderResolutionExtra() {
    var track = currentTrack();
    var settings = track && track.getSettings ? track.getSettings() : null;
    if (settings && settings.width && settings.height) {
      var mp = (settings.width * settings.height / 1e6).toFixed(1);
      stepExtra.innerHTML = '<div class="stat-grid"><div class="stat-tile highlight"><span class="stat-value">' +
        settings.width + '×' + settings.height + '</span><span class="stat-label">Reported Resolution</span></div>' +
        '<div class="stat-tile"><span class="stat-value">' + mp + ' MP</span><span class="stat-label">Megapixels</span></div></div>';
    } else {
      stepExtra.innerHTML = '<p class="field-note">Start the camera on the previous step to read its resolution.</p>';
    }
  }

  function renderTorchExtra() {
    stepExtra.innerHTML = '<div class="tool-actions"><button type="button" class="btn-secondary" id="btnTryTorch">Try Torch</button><span class="field-note mt-0 mb-0" id="torchStatus"></span></div>';
    var btnTryTorch = document.getElementById('btnTryTorch');
    var torchStatus = document.getElementById('torchStatus');
    btnTryTorch.addEventListener('click', function () {
      var track = currentTrack();
      if (!track) { torchStatus.textContent = 'Start the camera first.'; return; }
      var caps = track.getCapabilities ? (function () { try { return track.getCapabilities(); } catch (e) { return null; } })() : null;
      if (!caps || !caps.torch) {
        torchStatus.textContent = 'Torch control isn’t supported by this browser/lens — judge this step by eye on the phone itself instead.';
        return;
      }
      track.applyConstraints({ advanced: [{ torch: true }] })
        .then(function () {
          torchStatus.textContent = 'Torch turned on — confirm you can see it, then turn it off below.';
          btnTryTorch.textContent = 'Turn Torch Off';
          btnTryTorch.onclick = function () {
            track.applyConstraints({ advanced: [{ torch: false }] }).catch(function () {});
            renderTorchExtra();
          };
        })
        .catch(function () { torchStatus.textContent = 'Couldn’t toggle torch on this lens.'; });
    });
  }

  function renderCaptureExtra() {
    stepExtra.innerHTML = '<div class="tool-actions"><button type="button" class="btn-secondary" id="btnTakePhoto">Take Photo</button></div>';
    document.getElementById('btnTakePhoto').addEventListener('click', function () {
      if (!video.videoWidth) return;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      canvas.getContext('2d').drawImage(video, 0, 0);
      capturedPhotoUrl = canvas.toDataURL('image/jpeg', 0.9);
      summaryPhoto.src = capturedPhotoUrl;
      summaryPhoto.style.display = 'block';
      results.capture = 'pass';
      renderChecklist();
      renderSummaryCounts();
    });
  }

  function renderStep() {
    var step = STEPS[stepIndex];
    stepTitle.textContent = 'Step ' + (stepIndex + 1) + ' of ' + STEPS.length + ' — ' + step.title;
    stepSubtitle.textContent = step.subtitle;
    stepInstructions.textContent = step.instructions;

    if (step.id === 'resolution') renderResolutionExtra();
    else if (step.id === 'torch') renderTorchExtra();
    else if (step.id === 'capture') renderCaptureExtra();
    else stepExtra.innerHTML = '';

    btnPrevStep.disabled = stepIndex === 0;
    btnNextStep.textContent = stepIndex === STEPS.length - 1 ? 'Finish' : 'Next →';
    // Lens and capture grade themselves (a successful stream / a taken
    // photo IS the pass condition); every other step -- including
    // resolution, whose reported number is informational only -- needs a
    // human to look and judge, so Mark Pass/Fail stays enabled there.
    var manual = step.id !== 'lens' && step.id !== 'capture';
    btnMarkPass.disabled = !manual;
    btnMarkFail.disabled = !manual;
  }

  function renderChecklist() {
    checklistList.innerHTML = STEPS.map(function (s, i) {
      var status = results[s.id];
      var cls = status === 'pass' ? 'supported' : (status === 'fail' ? 'failed' : '');
      if (i === stepIndex) cls += ' current';
      var badge = status === 'pass' ? 'Pass' : (status === 'fail' ? 'Fail' : 'Pending');
      return '<div class="ladder-item clickable ' + cls + '" data-step="' + i + '"><span class="ladder-name">' + (i + 1) + '. ' + escapeHtml(s.title) + '</span><span class="ladder-dims">' + badge + '</span></div>';
    }).join('');
    Array.prototype.forEach.call(checklistList.querySelectorAll('[data-step]'), function (el) {
      el.addEventListener('click', function () {
        stepIndex = parseInt(el.getAttribute('data-step'), 10);
        renderStep();
        renderChecklist();
      });
    });
  }

  function renderSummaryCounts() {
    var pass = 0, fail = 0, pending = 0;
    STEPS.forEach(function (s) {
      if (results[s.id] === 'pass') pass++;
      else if (results[s.id] === 'fail') fail++;
      else pending++;
    });
    statPass.textContent = String(pass);
    statFail.textContent = String(fail);
    statPending.textContent = String(pending);
  }

  function buildSummaryText() {
    var lines = ['Used Phone Camera Inspection Summary', ''];
    STEPS.forEach(function (s, i) {
      var status = results[s.id] === 'pass' ? 'PASS' : (results[s.id] === 'fail' ? 'FAIL' : 'PENDING');
      lines.push((i + 1) + '. ' + s.title + ': ' + status);
    });
    lines.push('', capturedPhotoUrl ? 'Sample photo captured: yes' : 'Sample photo captured: no');
    return lines.join('\n');
  }

  btnStart.addEventListener('click', function () { startStream(deviceSelect.value); });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Camera stopped.' }]);
  });
  deviceSelect.addEventListener('change', function () { if (currentStream) startStream(deviceSelect.value); });

  btnMarkPass.addEventListener('click', function () {
    results[STEPS[stepIndex].id] = 'pass';
    renderChecklist();
    renderSummaryCounts();
  });
  btnMarkFail.addEventListener('click', function () {
    results[STEPS[stepIndex].id] = 'fail';
    renderChecklist();
    renderSummaryCounts();
  });
  btnPrevStep.addEventListener('click', function () {
    if (stepIndex > 0) { stepIndex--; renderStep(); renderChecklist(); }
  });
  btnNextStep.addEventListener('click', function () {
    if (stepIndex < STEPS.length - 1) { stepIndex++; renderStep(); renderChecklist(); }
  });

  btnCopySummary.addEventListener('click', function () {
    var text = buildSummaryText();
    (navigator.clipboard ? navigator.clipboard.writeText(text) : Promise.reject())
      .then(function () {
        var original = btnCopySummary.dataset.original || btnCopySummary.innerHTML;
        btnCopySummary.dataset.original = original;
        btnCopySummary.textContent = 'Copied!';
        setTimeout(function () { btnCopySummary.innerHTML = original; }, 1500);
      })
      .catch(function () {});
  });

  btnDownloadSummary.addEventListener('click', function () {
    var blob = new Blob([buildSummaryText()], { type: 'text/plain' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = 'phone-camera-inspection-summary.txt';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
  });

  window.addEventListener('pagehide', stopStream);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  renderChecklist();
  renderSummaryCounts();

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support camera access.</strong>' }]);
    btnStart.disabled = true;
  }
})();

(function () {
  'use strict';

  var video = document.getElementById('cameraVideo');
  var previewWrap = document.getElementById('cameraPreviewWrap');
  var placeholder = document.getElementById('cameraPlaceholder');
  var deviceSelect = document.getElementById('deviceSelect');
  var btnStart = document.getElementById('btnStartCamera');
  var btnStop = document.getElementById('btnStopCamera');
  var btnToggleTorch = document.getElementById('btnToggleTorch');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var btnWhiteScreen = document.getElementById('btnWhiteScreen');
  var btnCloseWhiteScreen = document.getElementById('btnCloseWhiteScreen');
  var whiteScreenOverlay = document.getElementById('whiteScreenOverlay');

  var currentStream = null;
  var starting = false;
  var torchOn = false;
  var torchSupported = false;

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  // Same stopStream()/describeError()/populateDeviceSelect() pattern as
  // webcam-test-online's own script (see this project's CLAUDE.md -- every
  // camera tool copies this teardown block rather than importing a shared file).
  function stopStream() {
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    video.srcObject = null;
    previewWrap.classList.remove('is-active');
    placeholder.style.display = 'flex';
    btnStop.disabled = true;
    btnToggleTorch.disabled = true;
    btnToggleTorch.textContent = 'Turn Torch On';
    torchOn = false;
    torchSupported = false;
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Camera access was blocked.</strong> Allow access from your browser’s address-bar icon or site settings, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No camera was detected.</strong> Connect a camera and reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your camera is already in use</strong> by another app or browser tab.' };
      case 'OverconstrainedError':
        return { sev: 'error', html: '<strong>This camera doesn’t support the requested settings.</strong> Try another camera from the list.' };
      case 'SecurityError':
        return { sev: 'error', html: '<strong>Camera access requires HTTPS.</strong>' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong starting the camera.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function populateDeviceSelect(devices, currentDeviceId) {
    var cams = devices.filter(function (d) { return d.kind === 'videoinput'; });
    deviceSelect.innerHTML = '';
    cams.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Camera ' + (i + 1));
      if (d.deviceId === currentDeviceId) opt.selected = true;
      deviceSelect.appendChild(opt);
    });
    deviceSelect.disabled = cams.length === 0;
  }

  // Torch capability only ever appears while a rear-camera stream is active,
  // per this tool's own spec note -- request facingMode:environment so
  // phones default to the lens that actually has a flash next to it.
  function startStream(deviceId) {
    if (starting) return;
    starting = true;
    stopStream();
    setDiagnostic([{ sev: '', html: 'Requesting camera access…' }]);
    btnStart.disabled = true;

    var constraints = deviceId
      ? { video: { deviceId: { exact: deviceId } }, audio: false }
      : { video: { facingMode: { ideal: 'environment' } }, audio: false };

    navigator.mediaDevices.getUserMedia(constraints)
      .then(function (stream) {
        currentStream = stream;
        video.srcObject = stream;
        placeholder.style.display = 'none';
        previewWrap.classList.add('is-active');
        return video.play().catch(function () {}).then(function () { return stream; });
      })
      .then(function (stream) {
        var track = stream.getVideoTracks()[0];
        var settings = track.getSettings ? track.getSettings() : {};
        var caps = track.getCapabilities ? (function () { try { return track.getCapabilities(); } catch (e) { return null; } })() : null;
        btnStop.disabled = false;
        torchSupported = !!(caps && caps.torch);
        if (torchSupported) {
          btnToggleTorch.disabled = false;
          setDiagnostic([{ sev: 'ok', html: '<strong>Camera is live and torch control is available.</strong> Use the button above to toggle it.' }]);
        } else {
          btnToggleTorch.disabled = true;
          setDiagnostic([{ sev: 'warn', html: '<strong>Camera is live, but this browser can’t control the flash directly.</strong> This is expected on iPhone (Safari never exposes torch to web pages) and on many Android browsers too — use the full-screen white light or your native camera app instead.' }]);
        }
        return navigator.mediaDevices.enumerateDevices().then(function (devices) {
          populateDeviceSelect(devices, settings.deviceId);
        });
      })
      .catch(function (err) { setDiagnostic([describeError(err)]); stopStream(); })
      .finally(function () { starting = false; btnStart.disabled = false; });
  }

  function toggleTorch() {
    if (!currentStream || !torchSupported) return;
    var track = currentStream.getVideoTracks()[0];
    var next = !torchOn;
    track.applyConstraints({ advanced: [{ torch: next }] })
      .then(function () {
        torchOn = next;
        btnToggleTorch.textContent = torchOn ? 'Turn Torch Off' : 'Turn Torch On';
        setDiagnostic([{ sev: 'ok', html: torchOn ? '<strong>Torch on.</strong> Confirm the LED next to the rear lens is lit.' : 'Torch turned off.' }]);
      })
      .catch(function () {
        setDiagnostic([{ sev: 'error', html: '<strong>Couldn’t toggle the torch</strong> even though it was reported as supported. Try the full-screen white light instead.' }]);
      });
  }

  function openWhiteScreen() {
    whiteScreenOverlay.style.display = 'flex';
    document.addEventListener('keydown', onWhiteScreenKeydown);
  }
  function closeWhiteScreen() {
    whiteScreenOverlay.style.display = 'none';
    document.removeEventListener('keydown', onWhiteScreenKeydown);
  }
  function onWhiteScreenKeydown(e) { if (e.key === 'Escape') closeWhiteScreen(); }

  btnStart.addEventListener('click', function () { startStream(deviceSelect.value); });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Camera stopped.' }]);
  });
  deviceSelect.addEventListener('change', function () { if (currentStream) startStream(deviceSelect.value); });
  btnToggleTorch.addEventListener('click', toggleTorch);
  btnWhiteScreen.addEventListener('click', openWhiteScreen);
  btnCloseWhiteScreen.addEventListener('click', closeWhiteScreen);

  window.addEventListener('pagehide', stopStream);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support camera access.</strong>' }]);
    btnStart.disabled = true;
  }
})();

(function () {
  'use strict';

  var searchInput = document.getElementById('searchInput');
  var btnDetectMax = document.getElementById('btnDetectMax');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var dataRows = document.getElementById('dataRows');

  // Same 18-entry standards list as webcam-maximum-resolution-detector.json,
  // kept in the same order/values deliberately so the ladder there and the
  // reference here never diverge, per this tool's own spec note.
  var STANDARDS = [
    { name: '8K UHD', w: 7680, h: 4320, use: 'Cinema and flagship broadcast production; no consumer webcam reaches this.' },
    { name: '5K', w: 5120, h: 2880, use: 'High-end professional monitors and studio cameras.' },
    { name: 'DCI 4K', w: 4096, h: 2160, use: 'Digital cinema projection standard (slightly wider than consumer 4K).' },
    { name: '4K UHD', w: 3840, h: 2160, use: 'Flagship webcams and modern TVs/monitors; common ceiling for premium streaming setups.' },
    { name: 'QHD+', w: 2560, h: 1600, use: 'High-DPI laptop displays; occasionally used by high-end integrated cameras.' },
    { name: 'QHD', w: 2560, h: 1440, use: 'Also called 1440p; a common upper tier for mid-range webcams.' },
    { name: 'Full HD+', w: 1920, h: 1200, use: '16:10 variant of 1080p, seen on some laptop displays and cameras.' },
    { name: 'Full HD', w: 1920, h: 1080, use: 'The de facto standard for webcams and video calls today — 1080p.' },
    { name: 'HD+', w: 1600, h: 900, use: 'A step below 1080p, common on older or budget laptop webcams.' },
    { name: 'HD', w: 1280, h: 720, use: '720p — the long-standing baseline "HD" resolution for video calls.' },
    { name: 'XGA', w: 1024, h: 768, use: 'A legacy 4:3 computer display standard, still used by some older webcams.' },
    { name: 'WSVGA', w: 1024, h: 600, use: 'Older small-laptop displays and low-cost integrated cameras.' },
    { name: 'SVGA', w: 800, h: 600, use: 'An early-2000s webcam and monitor standard.' },
    { name: 'VGA', w: 640, h: 480, use: 'The original webcam resolution — still the fallback on many low-end or older devices.' },
    { name: 'CIF', w: 352, h: 288, use: 'Common Intermediate Format — an old video-conferencing standard.' },
    { name: 'QVGA', w: 320, h: 240, use: 'Quarter-VGA; used on very old or low-power devices.' },
    { name: 'QCIF', w: 176, h: 144, use: 'Quarter-CIF; found on legacy mobile video calling.' },
    { name: 'QQVGA', w: 160, h: 120, use: 'The smallest common standard — early feature-phone camera previews.' },
  ];

  function gcd(a, b) { return b === 0 ? a : gcd(b, a % b); }
  STANDARDS.forEach(function (s) {
    s.area = s.w * s.h;
    s.mp = s.area / 1e6;
    var g = gcd(s.w, s.h) || 1;
    s.aspect = (s.w / g) + ':' + (s.h / g);
  });

  var sortKey = 'area';
  var sortDir = -1; // descending by default (8K first)
  var highlightArea = null;

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(html) {
    if (!html) { diagnosticPanel.style.display = 'none'; return; }
    diagnosticPanel.style.display = 'flex';
    diagnosticPanel.querySelector('span:last-child').innerHTML = html;
  }

  function render() {
    var query = searchInput.value.trim().toLowerCase();
    var rows = STANDARDS.filter(function (s) { return s.name.toLowerCase().indexOf(query) !== -1; });
    rows.sort(function (a, b) {
      var av = a[sortKey], bv = b[sortKey];
      if (typeof av === 'string') return av.localeCompare(bv) * sortDir;
      return (av - bv) * sortDir;
    });
    dataRows.innerHTML = rows.map(function (s) {
      var isHighlight = highlightArea !== null && s.area === highlightArea;
      return '<div class="data-row' + (isHighlight ? ' highlight' : '') + '" data-area="' + s.area + '">' +
        '<span class="data-name">' + escapeHtml(s.name) + '</span>' +
        '<span class="data-dims">' + s.w + '×' + s.h + '</span>' +
        '<span class="data-mp">' + s.mp.toFixed(2) + ' MP</span>' +
        '<span class="data-aspect">' + s.aspect + '</span>' +
        '<span>' + escapeHtml(s.use) + '</span></div>';
    }).join('');
  }

  document.querySelectorAll('.data-table-head [data-sort]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var key = btn.getAttribute('data-sort');
      if (sortKey === key) sortDir = -sortDir;
      else { sortKey = key; sortDir = key === 'name' || key === 'use' ? 1 : -1; }
      render();
    });
  });
  searchInput.addEventListener('input', render);

  // Runs the same descending-probe technique as
  // webcam-maximum-resolution-detector.json -- stop at the first standard
  // the browser can actually negotiate -- but headlessly (no live preview)
  // since this page's job is to highlight a row in the table, not show video.
  function detectMax() {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      setDiagnostic('<strong>Your browser doesn’t support camera access.</strong>');
      return;
    }
    btnDetectMax.disabled = true;
    setDiagnostic('Probing your camera — this briefly restarts it several times…');

    var sorted = STANDARDS.slice().sort(function (a, b) { return b.area - a.area; });
    var i = 0;
    var stream = null;

    function stopCurrent() {
      if (stream) { stream.getTracks().forEach(function (t) { t.stop(); }); stream = null; }
    }

    function next() {
      if (i >= sorted.length) return finish(null);
      var entry = sorted[i];
      stopCurrent();
      navigator.mediaDevices.getUserMedia({ video: { width: { ideal: entry.w }, height: { ideal: entry.h } }, audio: false })
        .then(function (s) {
          stream = s;
          var track = s.getVideoTracks()[0];
          var settings = track.getSettings ? track.getSettings() : {};
          var actualArea = (settings.width || 0) * (settings.height || 0);
          if (actualArea >= entry.area * 0.95) return finish(entry);
          i++;
          next();
        })
        .catch(function (err) {
          if (err && (err.name === 'OverconstrainedError' || err.name === 'ConstraintNotSatisfiedError')) {
            i++;
            next();
            return;
          }
          finish(null, err);
        });
    }

    function finish(found, err) {
      stopCurrent();
      btnDetectMax.disabled = false;
      if (!found) {
        if (err) {
          var msg = err.name === 'NotAllowedError' ? 'Camera access was blocked — allow access and try again.'
            : err.name === 'NotFoundError' ? 'No camera was detected on this device.'
            : err.name === 'NotReadableError' ? 'Your camera is already in use by another app or tab.'
            : 'Something went wrong probing your camera.';
          setDiagnostic('<strong>' + msg + '</strong>');
        } else {
          setDiagnostic('Could not match your camera to a standard resolution.');
        }
        highlightArea = null;
        render();
        return;
      }
      highlightArea = found.area;
      setDiagnostic('<strong>Your camera\'s maximum negotiated resolution is ' + found.w + '×' + found.h + ' (' + found.name + ')</strong> — highlighted in the table below.');
      render();
      var rowEl = dataRows.querySelector('[data-area="' + found.area + '"]');
      if (rowEl) rowEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }

    next();
  }

  btnDetectMax.addEventListener('click', detectMax);

  window.addEventListener('pagehide', function () {});

  render();
})();

(function () {
