    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  function resizeCanvas() {
    var rect = canvas.getBoundingClientRect();
    var dpr = window.devicePixelRatio || 1;
    canvas.width = Math.max(1, Math.round(rect.width * dpr));
    canvas.height = Math.max(1, Math.round(rect.height * dpr));
  }

  // Maps a pixel column to a frequency bin on a LOGARITHMIC axis -- a
  // linear axis compresses everything below 1 kHz (where most speech and
  // instrument fundamentals live) into an unreadable sliver, per this
  // tool's own spec note.
  function binForColumn(x, w, sampleRate) {
    var frac = x / w;
    var freq = minFreq * Math.pow(maxFreq / minFreq, frac);
    var bin = Math.round((freq / (sampleRate / 2)) * analyser.frequencyBinCount);
    return Math.max(0, Math.min(analyser.frequencyBinCount - 1, bin));
  }

  function drawFrame() {
    rafId = requestAnimationFrame(drawFrame);
    if (!analyser) return;
    analyser.getByteFrequencyData(freqData);

    var w = canvas.width, h = canvas.height;
    canvasCtx.clearRect(0, 0, w, h);

    var sampleRate = audioCtx.sampleRate;
    var maxVal = 0, maxBin = 0;
    for (var i = 0; i < freqData.length; i++) {
      if (freqData[i] > maxVal) { maxVal = freqData[i]; maxBin = i; }
    }

    var barCount = Math.max(1, Math.round(w / 3));
    var barWidth = w / barCount;
    for (var b = 0; b < barCount; b++) {
      var x = b * barWidth;
      var bin = binForColumn(x, w, sampleRate);
      var value = freqData[bin] / 255;
      var barH = value * h;
      canvasCtx.fillStyle = '#7c5cff';
      canvasCtx.fillRect(x, h - barH, Math.max(1, barWidth - 1), barH);

      if (!peakHold || peakHold.length !== barCount) peakHold = new Array(barCount).fill(0);
      if (value > peakHold[b]) peakHold[b] = value;
      else peakHold[b] = Math.max(0, peakHold[b] - 0.004);
      var peakY = h - peakHold[b] * h;
      canvasCtx.fillStyle = 'rgba(124,92,255,.55)';
      canvasCtx.fillRect(x, peakY, Math.max(1, barWidth - 1), 2);
    }

    if (maxVal > 10) {
      var dominantHz = Math.round((maxBin * (sampleRate / 2)) / analyser.frequencyBinCount);
      statDominant.textContent = dominantHz >= 1000 ? (dominantHz / 1000).toFixed(2) + ' kHz' : dominantHz + ' Hz';
    }

    // Mains hum: compare magnitude right at 50/60 Hz against the
    // surrounding noise floor -- a genuine hum spike stands out sharply
    // from nearby bins, unlike broadband noise.
    var hum50 = binMagnitude(50, sampleRate), hum60 = binMagnitude(60, sampleRate);
    var neighborhood = binMagnitude(150, sampleRate) + 15;
    if (hum50 > neighborhood && hum50 >= hum60) {
      statHum.textContent = '50 Hz detected';
    } else if (hum60 > neighborhood) {
      statHum.textContent = '60 Hz detected';
    } else {
      statHum.textContent = 'None detected';
    }
  }

  function binMagnitude(freq, sampleRate) {
    var bin = Math.round((freq / (sampleRate / 2)) * analyser.frequencyBinCount);
    bin = Math.max(0, Math.min(analyser.frequencyBinCount - 1, bin));
    return freqData[bin];
  }

  // Deliberately timer-driven, not requestAnimationFrame -- this is a
  // background measurement, not a rendering task, and rAF is fully
  // suspended whenever the tab isn't visible. A user briefly switching tabs
  // mid-measurement would otherwise leave this permanently stuck.
  function measureNoiseFloor() {
    if (!analyser || measuringFloor) return;
    measuringFloor = true;
    btnMeasureFloor.disabled = true;
    var samples = [];
    var intervalId = setInterval(function () {
      analyser.getByteFrequencyData(freqData);
      var sum = 0;
      for (var i = 0; i < freqData.length; i++) sum += freqData[i];
      samples.push(sum / freqData.length);
    }, 50);
    setTimeout(function () {
      clearInterval(intervalId);
      var avg = samples.reduce(function (a, b) { return a + b; }, 0) / samples.length;
      var db = avg > 0 ? Math.round(20 * Math.log10(avg / 255)) : -60;
      statNoiseFloor.textContent = db + ' dB';
      measuringFloor = false;
      btnMeasureFloor.disabled = false;
    }, 2000);
  }

  // Same overall stopStream() shape as microphone-test-online's own script
  // (see this project's CLAUDE.md) -- audio teardown additionally closes
  // the AudioContext.
  function stopStream() {
    if (rafId) { cancelAnimationFrame(rafId); rafId = null; }
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    if (audioCtx) {
      audioCtx.close().catch(function () {});
      audioCtx = null;
    }
    analyser = null;
    peakHold = null;
    canvasCtx.clearRect(0, 0, canvas.width, canvas.height);
    btnStop.disabled = true;
    btnMeasureFloor.disabled = true;
    statDominant.textContent = '—';
    statNoiseFloor.textContent = '—';
    statHum.textContent = '—';
    statSampleRate.textContent = '—';
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Microphone access was blocked.</strong> Allow access from your browser’s address-bar icon or site settings, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No microphone was detected.</strong> Connect a microphone and reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your microphone is already in use</strong> by another app or browser tab.' };
      case 'OverconstrainedError':
        return { sev: 'error', html: '<strong>This microphone doesn’t support the requested settings.</strong> Try another microphone from the list.' };
      case 'SecurityError':
        return { sev: 'error', html: '<strong>Microphone access requires HTTPS.</strong>' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong starting the microphone.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function populateDeviceSelect(devices, currentDeviceId) {
    var mics = devices.filter(function (d) { return d.kind === 'audioinput'; });
    deviceSelect.innerHTML = '';
    mics.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Microphone ' + (i + 1));
      if (d.deviceId === currentDeviceId) opt.selected = true;
      deviceSelect.appendChild(opt);
    });
    deviceSelect.disabled = mics.length === 0;
  }

  function startMic(deviceId) {
    if (starting) return;
    starting = true;
    stopStream();
    resizeCanvas();
    setDiagnostic([{ sev: '', html: 'Requesting microphone access…' }]);
    btnStart.disabled = true;

    // echoCancellation/noiseSuppression/autoGainControl are ON by default
    // and will actively distort the spectrum -- disabling them is the one
    // thing that makes this measurement meaningful, per this tool's own
    // spec note.
    var constraints = {
      audio: {
        deviceId: deviceId ? { exact: deviceId } : undefined,
        echoCancellation: false,
        noiseSuppression: false,
        autoGainControl: false,
      },
    };

    navigator.mediaDevices.getUserMedia(constraints)
      .then(function (stream) {
        currentStream = stream;
        audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        var source = audioCtx.createMediaStreamSource(stream);
        analyser = audioCtx.createAnalyser();
        analyser.fftSize = 2048;
        analyser.smoothingTimeConstant = 0.7;
        freqData = new Uint8Array(analyser.frequencyBinCount);
        source.connect(analyser);

        var track = stream.getAudioTracks()[0];
        var settings = track.getSettings ? track.getSettings() : {};
        statSampleRate.textContent = Math.round(audioCtx.sampleRate) + ' Hz';
        btnStop.disabled = false;
        btnMeasureFloor.disabled = false;
        setDiagnostic([{ sev: 'ok', html: '<strong>Microphone is live.</strong> Make some noise to see the spectrum respond, or stay silent and measure your noise floor.' }]);
        drawFrame();

        return navigator.mediaDevices.enumerateDevices().then(function (devices) {
          populateDeviceSelect(devices, settings.deviceId);
        });
      })
      .catch(function (err) { setDiagnostic([describeError(err)]); stopStream(); })
      .finally(function () { starting = false; btnStart.disabled = false; });
  }

  btnStart.addEventListener('click', function () { startMic(deviceSelect.value); });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Microphone stopped.' }]);
  });
  deviceSelect.addEventListener('change', function () { if (currentStream) startMic(deviceSelect.value); });
  btnMeasureFloor.addEventListener('click', measureNoiseFloor);

  window.addEventListener('resize', resizeCanvas);
  window.addEventListener('pagehide', stopStream);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  resizeCanvas();

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support microphone access.</strong>' }]);
    btnStart.disabled = true;
  }
})();

(function () {
  'use strict';

  var btnStart = document.getElementById('btnStartSweep');
  var btnPause = document.getElementById('btnPauseSweep');
  var btnStop = document.getElementById('btnStopSweep');
  var freqReadout = document.getElementById('freqReadout');
  var progressFill = document.getElementById('sweepProgressFill');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var durationSlider = document.getElementById('durationSlider');
  var durationValue = document.getElementById('durationValue');
  var volumeSlider = document.getElementById('volumeSlider');
  var volumeValue = document.getElementById('volumeValue');
  var manualFreqSlider = document.getElementById('manualFreqSlider');
  var manualFreqValue = document.getElementById('manualFreqValue');

  var MAX_GAIN = 0.3; // conservative ceiling -- see this site's safety notes for playback tools; a sweep can be uncomfortable/damaging at full volume
  var MIN_FREQ = 20, MAX_FREQ = 20000;

  var audioCtx = null;
  var oscillator = null;
  var gainNode = null;
  var tickIntervalId = null;
  var sweeping = false;
  var paused = false;
  var elapsed = 0; // seconds of sweep progress
  var lastTick = 0;

  function setDiagnostic(sev, html) {
    diagnosticPanel.innerHTML = '<div class="diagnostic-item' + (sev ? ' sev-' + sev : '') + '"><span class="diag-icon" aria-hidden="true">' +
      '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
      '</span><span>' + html + '</span></div>';
  }

  function ensureContext() {
    if (!audioCtx) {
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      oscillator = audioCtx.createOscillator();
      gainNode = audioCtx.createGain();
      oscillator.type = 'sine';
      oscillator.frequency.value = MIN_FREQ;
      gainNode.gain.value = 0;
      oscillator.connect(gainNode);
      gainNode.connect(audioCtx.destination);
      oscillator.start();
    }
    return audioCtx.resume().catch(function () {});
  }

  function currentGainTarget() {
    return (parseFloat(volumeSlider.value) / 100) * MAX_GAIN;
  }

  function formatFreq(hz) {
    return hz >= 1000 ? (hz / 1000).toFixed(2) + ' kHz' : Math.round(hz) + ' Hz';
  }

  // Exponential ramp, not linear -- a linear sweep from 20-20000 Hz spends
  // almost its entire duration above 10 kHz and blows through the whole
  // musically/audibly relevant range in the first fraction of a second,
  // per this tool's own spec note.
  function freqAtElapsed(t, duration) {
    var frac = Math.max(0, Math.min(1, t / duration));
    return MIN_FREQ * Math.pow(MAX_FREQ / MIN_FREQ, frac);
  }

  // Timer-driven, not requestAnimationFrame -- this updates the oscillator's
  // actual frequency (an audible side effect the visitor may be listening
  // to), not just an on-screen readout, and rAF is fully suspended whenever
  // the tab isn't visible. A user briefly switching tabs mid-sweep should
  // still hear it continue and finish on schedule.
  function tick() {
    if (!sweeping || paused) return;
    var now = performance.now();
    if (!lastTick) lastTick = now;
    var dt = (now - lastTick) / 1000;
    lastTick = now;
    var duration = parseFloat(durationSlider.value);
    elapsed += dt;
    if (elapsed >= duration) {
      elapsed = duration;
      var freq = freqAtElapsed(elapsed, duration);
      oscillator.frequency.setValueAtTime(freq, audioCtx.currentTime);
      freqReadout.textContent = formatFreq(freq);
      progressFill.style.width = '100%';
      finishSweep();
      return;
    }
    var freqNow = freqAtElapsed(elapsed, duration);
    oscillator.frequency.setValueAtTime(freqNow, audioCtx.currentTime);
    freqReadout.textContent = formatFreq(freqNow);
    progressFill.style.width = Math.round((elapsed / duration) * 100) + '%';
  }

  function finishSweep() {
    sweeping = false;
    stopTickLoop();
    rampGainTo(0);
    btnStart.textContent = 'Start Sweep';
    btnPause.disabled = true;
    btnStop.disabled = true;
    setDiagnostic('ok', '<strong>Sweep finished.</strong> Note the frequency shown if you heard a dropout, rattle or resonance, and use the manual slider to zero in on it.');
  }

  function rampGainTo(target) {
    if (!gainNode || !audioCtx) return;
    var now = audioCtx.currentTime;
    gainNode.gain.cancelScheduledValues(now);
    gainNode.gain.setValueAtTime(gainNode.gain.value, now);
    gainNode.gain.linearRampToValueAtTime(target, now + 0.05);
  }

  function startTickLoop() {
    if (tickIntervalId) clearInterval(tickIntervalId);
    tickIntervalId = setInterval(tick, 30);
  }
  function stopTickLoop() {
    if (tickIntervalId) { clearInterval(tickIntervalId); tickIntervalId = null; }
  }

  function startSweep() {
    ensureContext().then(function () {
      elapsed = 0;
      lastTick = 0;
      sweeping = true;
      paused = false;
      rampGainTo(currentGainTarget());
      btnStart.textContent = 'Restart Sweep';
      btnPause.disabled = false;
      btnPause.textContent = 'Pause';
      btnStop.disabled = false;
      setDiagnostic('ok', '<strong>Sweeping…</strong> Listen for any point where the tone drops out, rattles, or seems to resonate unusually loud.');
      startTickLoop();
    });
  }

  function togglePause() {
    if (!sweeping) return;
    paused = !paused;
    btnPause.textContent = paused ? 'Resume' : 'Pause';
    if (paused) {
      rampGainTo(0);
    } else {
      lastTick = 0;
      rampGainTo(currentGainTarget());
      startTickLoop();
    }
  }

  function stopSweep() {
    sweeping = false;
    paused = false;
    stopTickLoop();
    rampGainTo(0);
    progressFill.style.width = '0%';
    freqReadout.textContent = '—';
    btnStart.textContent = 'Start Sweep';
    btnPause.disabled = true;
    btnStop.disabled = true;
    setDiagnostic('', 'Stopped.');
  }

  function playManualFrequency() {
    ensureContext().then(function () {
      sweeping = false;
      paused = false;
      btnPause.disabled = true;
      btnStop.disabled = false;
      var pct = parseFloat(manualFreqSlider.value) / 1000;
      var freq = MIN_FREQ * Math.pow(MAX_FREQ / MIN_FREQ, pct);
      oscillator.frequency.setValueAtTime(freq, audioCtx.currentTime);
      manualFreqValue.textContent = formatFreq(freq);
      freqReadout.textContent = formatFreq(freq);
      rampGainTo(currentGainTarget());
      setDiagnostic('ok', '<strong>Playing ' + formatFreq(freq) + ' steadily.</strong> Click Stop when done.');
    });
  }

  btnStart.addEventListener('click', startSweep);
  btnPause.addEventListener('click', togglePause);
  btnStop.addEventListener('click', stopSweep);

  durationSlider.addEventListener('input', function () {
    durationValue.textContent = durationSlider.value + ' s';
  });
  volumeSlider.addEventListener('input', function () {
    volumeValue.textContent = volumeSlider.value + '%';
    if (sweeping && !paused) rampGainTo(currentGainTarget());
  });
  manualFreqSlider.addEventListener('input', function () {
    var pct = parseFloat(manualFreqSlider.value) / 1000;
    var freq = MIN_FREQ * Math.pow(MAX_FREQ / MIN_FREQ, pct);
    manualFreqValue.textContent = formatFreq(freq);
  });
  manualFreqSlider.addEventListener('change', playManualFrequency);
  manualFreqSlider.dispatchEvent(new Event('input'));

  window.addEventListener('pagehide', function () {
    sweeping = false;
    stopTickLoop();
    if (audioCtx) { audioCtx.close().catch(function () {}); audioCtx = null; }
  });
  document.addEventListener('visibilitychange', function () {
    // Silence (rather than let it keep sweeping unheard) when the tab is
    // hidden -- a diagnostic tone playing on unattended, especially at the
    // high-frequency end, isn't something to leave running invisibly.
    if (document.visibilityState === 'hidden') {
      sweeping = false;
      stopTickLoop();
      if (gainNode && audioCtx) rampGainTo(0);
    }
  });

  if (!(window.AudioContext || window.webkitAudioContext)) {
    setDiagnostic('error', '<strong>Your browser doesn’t support the Web Audio API.</strong>');
    btnStart.disabled = true;
  }
})();

(function () {
  'use strict';

  var stepTitle = document.getElementById('stepTitle');
  var stepSubtitle = document.getElementById('stepSubtitle');
  var freqReadout = document.getElementById('freqReadout');
  var btnPrimary = document.getElementById('btnPrimaryAction');
  var btnCantHear = document.getElementById('btnCantHear');
  var btnRestart = document.getElementById('btnRestart');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var statResult = document.getElementById('statResult');
  var ageTable = document.getElementById('ageTable');

  var MAX_GAIN = 0.25; // deliberately conservative -- see this tool's own safety note (cap output level)
  var RAMP_SECONDS = 0.05;
  var REFERENCE_FREQ = 1000;

  // Ascending sequence from 8 kHz upward, per this tool's own spec.
  var TEST_FREQUENCIES = [8000, 10000, 12000, 13000, 14000, 15000, 16000, 17000, 18000, 19000, 20000];

  var audioCtx = null;
  var oscillator = null;
  var gainNode = null;
  var phase = 'reference'; // 'reference' -> 'testing' -> 'done'
  var stepIndex = -1;

  function setDiagnostic(sev, html) {
    diagnosticPanel.innerHTML = '<div class="diagnostic-item' + (sev ? ' sev-' + sev : '') + '"><span class="diag-icon" aria-hidden="true">' +
      '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
      '</span><span>' + html + '</span></div>';
  }

  function ensureContext() {
    if (!audioCtx) {
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      oscillator = audioCtx.createOscillator();
      gainNode = audioCtx.createGain();
      oscillator.type = 'sine';
      oscillator.frequency.value = REFERENCE_FREQ;
      gainNode.gain.value = 0;
      oscillator.connect(gainNode);
      gainNode.connect(audioCtx.destination);
      oscillator.start();
    }
    return audioCtx.resume().catch(function () {});
  }

  function rampGainTo(target) {
    if (!gainNode || !audioCtx) return;
    var now = audioCtx.currentTime;
    gainNode.gain.cancelScheduledValues(now);
    gainNode.gain.setValueAtTime(gainNode.gain.value, now);
    gainNode.gain.linearRampToValueAtTime(target, now + RAMP_SECONDS);
  }

  function formatFreq(hz) {
    return hz >= 1000 ? (hz / 1000).toFixed(hz % 1000 === 0 ? 0 : 1) + ' kHz' : hz + ' Hz';
  }

  function playReferenceTone() {
    ensureContext().then(function () {
      oscillator.frequency.setValueAtTime(REFERENCE_FREQ, audioCtx.currentTime);
      freqReadout.textContent = formatFreq(REFERENCE_FREQ);
      rampGainTo(MAX_GAIN);
      setDiagnostic('ok', '<strong>Playing a 1 kHz reference tone.</strong> Adjust your device volume to a comfortable, clearly audible level, then continue.');
      btnPrimary.textContent = 'Volume Is Set — Start Test';
      btnPrimary.onclick = beginTest;
    });
  }

  function beginTest() {
    phase = 'testing';
    stepIndex = 0;
    stepTitle.textContent = 'Step 2 — Ascending Tones';
    stepSubtitle.textContent = 'Click "I can’t hear it anymore" the moment a tone disappears';
    btnPrimary.style.display = 'none';
    btnCantHear.style.display = '';
    playCurrentStep();
  }

  function playCurrentStep() {
    var freq = TEST_FREQUENCIES[stepIndex];
    ensureContext().then(function () {
      oscillator.frequency.setValueAtTime(freq, audioCtx.currentTime);
      freqReadout.textContent = formatFreq(freq);
      rampGainTo(MAX_GAIN);
      setDiagnostic('', '<strong>Playing ' + formatFreq(freq) + '.</strong> If you can hear this, wait a moment — it advances automatically to the next tone. Click the button the instant it disappears.');
    });
  }

  function advanceOrFinish() {
    stepIndex++;
    if (stepIndex >= TEST_FREQUENCIES.length) {
      finishTest(TEST_FREQUENCIES[TEST_FREQUENCIES.length - 1], true);
    } else {
      playCurrentStep();
    }
  }

  function finishTest(highestHeard, reachedEnd) {
    phase = 'done';
    rampGainTo(0);
    var resultText = reachedEnd ? formatFreq(highestHeard) + '+ (test limit)' : formatFreq(highestHeard);
    statResult.textContent = resultText;
    freqReadout.textContent = resultText;
    stepTitle.textContent = 'Result';
    stepSubtitle.textContent = 'Remember: this is a rough, informal estimate, not a medical measurement';
    btnCantHear.style.display = 'none';
    btnRestart.style.display = '';
    setDiagnostic('ok', reachedEnd
      ? '<strong>You could hear every tone up to the top of this test (' + formatFreq(highestHeard) + ').</strong> Many playback devices roll off well before this point regardless of hearing ability, so this is a good result, not necessarily exceptional hearing.'
      : '<strong>Your estimated ceiling is around ' + formatFreq(highestHeard) + '.</strong> Remember this depends heavily on your speakers/headphones — a different device could easily give a different result.');
    highlightBracket(highestHeard);
  }

  function highlightBracket(hz) {
    var bracket = hz >= 19000 ? 'teens' : hz >= 17000 ? '20s' : hz >= 15000 ? '30s' : hz >= 13000 ? '40s' : hz >= 11000 ? '50s' : '60plus';
    Array.prototype.forEach.call(ageTable.querySelectorAll('.info-row'), function (row) {
      row.classList.toggle('highlight-row', row.getAttribute('data-bracket') === bracket);
      if (row.getAttribute('data-bracket') === bracket) {
        row.style.background = 'var(--accent-softer)';
        row.style.borderColor = 'var(--accent)';
      }
    });
  }

  function restartTest() {
    phase = 'reference';
    stepIndex = -1;
    stepTitle.textContent = 'Step 1 — Set Your Volume';
    stepSubtitle.textContent = 'Play a comfortable reference tone before the test begins';
    freqReadout.textContent = formatFreq(REFERENCE_FREQ);
    statResult.textContent = 'Not tested yet';
    btnPrimary.style.display = '';
    btnPrimary.textContent = 'Play Reference Tone';
    btnPrimary.onclick = playReferenceTone;
    btnCantHear.style.display = 'none';
    btnRestart.style.display = 'none';
    rampGainTo(0);
    Array.prototype.forEach.call(ageTable.querySelectorAll('.info-row'), function (row) {
      row.style.background = '';
      row.style.borderColor = '';
    });
    setDiagnostic('', 'Set your volume to a comfortable, moderate level, then click Play Reference Tone.');
  }

  btnPrimary.addEventListener('click', playReferenceTone);
  btnCantHear.addEventListener('click', function () {
    if (phase !== 'testing') return;
    var lastHeard = stepIndex > 0 ? TEST_FREQUENCIES[stepIndex - 1] : null;
    if (lastHeard === null) {
      finishTest(TEST_FREQUENCIES[0] - 1000, false);
    } else {
      finishTest(lastHeard, false);
    }
  });
  btnRestart.addEventListener('click', restartTest);

  // Each test tone auto-advances after a few seconds if the visitor doesn't
  // click "can't hear it" -- silence gives no signal either way, so
  // advancing (rather than waiting forever) keeps the test moving.
  setInterval(function () {
