  function ensureContext() {
    if (!audioCtx) {
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      oscillator = audioCtx.createOscillator();
      gainNode = audioCtx.createGain();
      oscillator.type = 'sine';
      gainNode.gain.value = 0;
      oscillator.connect(gainNode);
      gainNode.connect(audioCtx.destination);
      oscillator.start();
    }
    return audioCtx.resume().catch(function () {});
  }

  function currentGainTarget() {
    return (parseFloat(volumeSlider.value) / 100) * MAX_GAIN;
  }

  function rampGainTo(target) {
    if (!gainNode || !audioCtx) return;
    var now = audioCtx.currentTime;
    gainNode.gain.cancelScheduledValues(now);
    gainNode.gain.setValueAtTime(gainNode.gain.value, now);
    gainNode.gain.linearRampToValueAtTime(target, now + RAMP_SECONDS);
  }

  function stopSweep() {
    if (sweepIntervalId) { clearInterval(sweepIntervalId); sweepIntervalId = null; }
    sweeping = false;
    btnSweep.textContent = 'Start Sweep (10s)';
  }

  function stopAll() {
    stopSweep();
    rampGainTo(0);
    if (activeBtn) { activeBtn.classList.remove('active'); activeBtn.setAttribute('aria-pressed', 'false'); activeBtn = null; }
    btnStop.disabled = true;
    freqReadout.textContent = '—';
  }

  function playFrequency(freq, btn) {
    stopSweep();
    ensureContext().then(function () {
      oscillator.frequency.setValueAtTime(freq, audioCtx.currentTime);
      rampGainTo(currentGainTarget());
      if (activeBtn) { activeBtn.classList.remove('active'); activeBtn.setAttribute('aria-pressed', 'false'); }
      activeBtn = btn;
      if (btn) { btn.classList.add('active'); btn.setAttribute('aria-pressed', 'true'); }
      btnStop.disabled = false;
      freqReadout.textContent = formatFreq(freq);
      setDiagnostic('ok', '<strong>Playing ' + formatFreq(freq) + '.</strong> If you hear nothing and your speaker is small, that\'s likely a hardware limitation, not a fault -- see the guide alongside this.');
    });
  }

  // Timer-driven (not requestAnimationFrame) since this updates the
  // oscillator's actual frequency -- an audible side effect -- not just a
  // rendering readout, per the rAF-vs-timer distinction established
  // elsewhere in this project.
  function startSweep() {
    if (sweeping) { stopAll(); setDiagnostic('', 'Stopped.'); return; }
    ensureContext().then(function () {
      if (activeBtn) { activeBtn.classList.remove('active'); activeBtn.setAttribute('aria-pressed', 'false'); activeBtn = null; }
      sweeping = true;
      sweepElapsed = 0;
      sweepLastTick = 0;
      btnSweep.textContent = 'Stop Sweep';
      btnStop.disabled = false;
      rampGainTo(currentGainTarget());
      setDiagnostic('ok', '<strong>Sweeping 20–150 Hz…</strong> Listen for any point where a rattle appears or the sound drops out.');
      sweepIntervalId = setInterval(tickSweep, 40);
    });
  }

  function tickSweep() {
    var now = performance.now();
    if (!sweepLastTick) sweepLastTick = now;
    var dt = (now - sweepLastTick) / 1000;
    sweepLastTick = now;
    sweepElapsed += dt;
    if (sweepElapsed >= SWEEP_DURATION) {
      stopAll();
      setDiagnostic('ok', '<strong>Sweep finished.</strong> Note the frequency shown if you heard a rattle or dropout.');
      return;
    }
    var frac = sweepElapsed / SWEEP_DURATION;
    var freq = MIN_SWEEP * Math.pow(MAX_SWEEP / MIN_SWEEP, frac);
    oscillator.frequency.setValueAtTime(freq, audioCtx.currentTime);
    freqReadout.textContent = formatFreq(freq);
  }

  freqButtons.forEach(function (btn) {
    btn.setAttribute('aria-pressed', 'false');
    btn.addEventListener('click', function () {
      playFrequency(parseFloat(btn.getAttribute('data-freq')), btn);
    });
  });

  btnStop.addEventListener('click', function () {
    stopAll();
    setDiagnostic('', 'Stopped.');
  });
  btnSweep.addEventListener('click', startSweep);

  volumeSlider.addEventListener('input', function () {
    volumeValue.textContent = volumeSlider.value + '%';
    if ((activeBtn || sweeping) && audioCtx) rampGainTo(currentGainTarget());
  });

  window.addEventListener('pagehide', function () {
    stopSweep();
    if (audioCtx) { audioCtx.close().catch(function () {}); audioCtx = null; }
  });
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopAll();
  });

  if (!(window.AudioContext || window.webkitAudioContext)) {
    setDiagnostic('error', '<strong>Your browser doesn’t support the Web Audio API.</strong>');
    freqButtons.forEach(function (b) { b.disabled = true; });
    btnSweep.disabled = true;
  }
})();

(function () {
  'use strict';

  var btnStartTest = document.getElementById('btnStartTest');
  var btnHeardIt = document.getElementById('btnHeardIt');
  var trialReadout = document.getElementById('trialReadout');
  var trialProgressFill = document.getElementById('trialProgressFill');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var statEstimate = document.getElementById('statEstimate');
  var statHardware = document.getElementById('statHardware');

  var TRIAL_COUNT = 8;
  var MAX_GAIN = 0.4;
  var AVG_HUMAN_REACTION_MS = 190; // typical average human auditory reaction time, subtracted from the raw measurement

  var audioCtx = null;
  var running = false;
  var trialIndex = 0;
  var results = [];
  var toneStartTime = null;
  var waitingForTone = false;
  var toneTimeoutId = null;

  function setDiagnostic(sev, html) {
    diagnosticPanel.innerHTML = '<div class="diagnostic-item' + (sev ? ' sev-' + sev : '') + '"><span class="diag-icon" aria-hidden="true">' +
      '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
      '</span><span>' + html + '</span></div>';
  }

  function ensureContext() {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    return audioCtx.resume().catch(function () {});
  }

  function reportHardwareLatency() {
    if (!audioCtx) return;
    var parts = [];
    if (typeof audioCtx.baseLatency === 'number') parts.push('base ' + Math.round(audioCtx.baseLatency * 1000) + ' ms');
    if (typeof audioCtx.outputLatency === 'number') parts.push('output ' + Math.round(audioCtx.outputLatency * 1000) + ' ms');
    statHardware.textContent = parts.length ? parts.join(', ') : 'Not reported';
  }

  function playTone() {
    ensureContext().then(function () {
      reportHardwareLatency();
      var osc = audioCtx.createOscillator();
      var gain = audioCtx.createGain();
      osc.type = 'sine';
      osc.frequency.value = 880;
      gain.gain.value = 0;
      osc.connect(gain);
      gain.connect(audioCtx.destination);
      osc.start();
      var now = audioCtx.currentTime;
      gain.gain.linearRampToValueAtTime(MAX_GAIN, now + 0.01);
      gain.gain.setValueAtTime(MAX_GAIN, now + 0.15);
      gain.gain.linearRampToValueAtTime(0, now + 0.18);
      setTimeout(function () { try { osc.stop(); osc.disconnect(); gain.disconnect(); } catch (e) {} }, 250);

      toneStartTime = performance.now();
      waitingForTone = true;
      btnHeardIt.disabled = false;
      // A trial with no click within 1.5s is treated as missed and discarded
      // rather than left hanging indefinitely.
      toneTimeoutId = setTimeout(function () {
        if (waitingForTone) {
          waitingForTone = false;
          btnHeardIt.disabled = true;
          nextTrial();
        }
      }, 1500);
    });
  }

  function scheduleTrial() {
    trialIndex++;
    trialReadout.textContent = 'Trial ' + trialIndex + ' of ' + TRIAL_COUNT;
    trialProgressFill.style.width = Math.round(((trialIndex - 1) / TRIAL_COUNT) * 100) + '%';
    setDiagnostic('', 'Get ready…');
    // Random 1-3s wait before each tone so the visitor can't anticipate the
    // exact timing, per this tool's own spec note.
    var wait = 1000 + Math.random() * 2000;
    setTimeout(function () {
      if (running) playTone();
    }, wait);
  }

  function nextTrial() {
    if (trialIndex >= TRIAL_COUNT) {
      finishTest();
    } else {
      scheduleTrial();
    }
  }

  function finishTest() {
    running = false;
    trialProgressFill.style.width = '100%';
    btnStartTest.disabled = false;
    btnStartTest.textContent = 'Run Test Again';
    btnHeardIt.disabled = true;

    if (results.length < 3) {
      setDiagnostic('warn', '<strong>Not enough valid trials to estimate.</strong> Try again and click as soon as you hear each tone.');
      statEstimate.textContent = 'Inconclusive';
      return;
    }

    // Discard outliers (implausibly fast/slow) before averaging, per this
    // tool's own spec note ("discard outliers, report a range").
    var sorted = results.slice().sort(function (a, b) { return a - b; });
    var filtered = sorted.filter(function (v) { return v > 80 && v < 1200; });
    var mean = filtered.reduce(function (a, b) { return a + b; }, 0) / filtered.length;
    var estimate = Math.max(0, Math.round(mean - AVG_HUMAN_REACTION_MS));
    var spread = Math.round((filtered[filtered.length - 1] - filtered[0]) / 2) || 15;
    var low = Math.max(0, estimate - spread);
    var high = estimate + spread;

    statEstimate.textContent = low + '–' + high + ' ms';
    setDiagnostic('ok', '<strong>Estimated audio latency: ' + low + '–' + high + ' ms.</strong> This range already accounts for typical human reaction time (~190 ms), subtracted from your raw average of ' + Math.round(mean) + ' ms across ' + filtered.length + ' valid trials.');
  }

  function startTest() {
    if (running) return;
    running = true;
    trialIndex = 0;
    results = [];
    btnStartTest.disabled = true;
    btnStartTest.textContent = 'Testing…';
    trialProgressFill.style.width = '0%';
    scheduleTrial();
  }

  btnStartTest.addEventListener('click', startTest);
  btnHeardIt.addEventListener('click', function () {
    if (!waitingForTone) return;
    waitingForTone = false;
    if (toneTimeoutId) clearTimeout(toneTimeoutId);
    var reaction = performance.now() - toneStartTime;
    results.push(reaction);
    btnHeardIt.disabled = true;
    nextTrial();
  });

  window.addEventListener('pagehide', function () {
    running = false;
    if (audioCtx) { audioCtx.close().catch(function () {}); audioCtx = null; }
  });
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') running = false;
  });

  if (!(window.AudioContext || window.webkitAudioContext)) {
    setDiagnostic('error', '<strong>Your browser doesn’t support the Web Audio API.</strong>');
    btnStartTest.disabled = true;
  }
})();

(function () {
  'use strict';

  var preEnableGate = document.getElementById('preEnableGate');
  var controlsArea = document.getElementById('controlsArea');
  var btnConfirmHeadphones = document.getElementById('btnConfirmHeadphones');
  var btnKillSwitch = document.getElementById('btnKillSwitch');
  var deviceSelect = document.getElementById('deviceSelect');
  var delaySlider = document.getElementById('delaySlider');
  var delayValue = document.getElementById('delayValue');
  var diagnosticPanel = document.getElementById('diagnosticPanel');

  var MAX_GAIN = 0.35; // capped -- see this tool's own safety note
  var RAMP_SECONDS = 0.6; // ramps in gradually rather than snapping to full volume

  var currentStream = null;
  var audioCtx = null;
  var sourceNode = null;
  var delayNode = null;
  var gainNode = null;
  var starting = false;

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(sev, html) {
    diagnosticPanel.innerHTML = '<div class="diagnostic-item' + (sev ? ' sev-' + sev : '') + '"><span class="diag-icon" aria-hidden="true">' +
      '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
      '</span><span>' + html + '</span></div>';
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Microphone access was blocked.</strong> Allow access from your browser’s address-bar icon or site settings, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No microphone was detected.</strong> Connect a microphone and reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your microphone is already in use</strong> by another app or browser tab.' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong starting the microphone.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function populateDeviceSelect(devices, currentDeviceId) {
    var mics = devices.filter(function (d) { return d.kind === 'audioinput'; });
    deviceSelect.innerHTML = '';
    mics.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Microphone ' + (i + 1));
      if (d.deviceId === currentDeviceId) opt.selected = true;
      deviceSelect.appendChild(opt);
    });
    deviceSelect.disabled = mics.length === 0;
  }

  // SAFETY: this deliberately creates a feedback path (mic -> delay ->
  // speakers). Gated behind an explicit headphone confirmation, gain is
  // capped well below full scale, and it ramps in over half a second
  // rather than snapping on -- all per this tool's own spec note. The
  // kill switch (killAll) is the one control that must always work
  // instantly, with no ramp.
  function startMic(deviceId) {
    if (starting) return;
    starting = true;
    setDiagnostic('', 'Requesting microphone access…');

    navigator.mediaDevices.getUserMedia({ audio: { deviceId: deviceId ? { exact: deviceId } : undefined } })
      .then(function (stream) {
        currentStream = stream;
        audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        sourceNode = audioCtx.createMediaStreamSource(stream);
        delayNode = audioCtx.createDelay(1.0);
        delayNode.delayTime.value = parseFloat(delaySlider.value) / 1000;
        gainNode = audioCtx.createGain();
        gainNode.gain.value = 0;
        sourceNode.connect(delayNode);
        delayNode.connect(gainNode);
        gainNode.connect(audioCtx.destination);

        var now = audioCtx.currentTime;
        gainNode.gain.linearRampToValueAtTime(MAX_GAIN, now + RAMP_SECONDS);

        var track = stream.getAudioTracks()[0];
        var settings = track.getSettings ? track.getSettings() : {};
        setDiagnostic('ok', '<strong>Echo is live.</strong> Speak normally and listen through your headphones. Use the kill switch below the instant you need to stop.');
        return navigator.mediaDevices.enumerateDevices().then(function (devices) {
          populateDeviceSelect(devices, settings.deviceId);
        });
