  // immediately under any circumstance, per this tool's own safety note.
  function killAll() {
    if (gainNode && audioCtx) {
      gainNode.gain.cancelScheduledValues(audioCtx.currentTime);
      gainNode.gain.setValueAtTime(0, audioCtx.currentTime);
    }
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    if (audioCtx) {
      audioCtx.close().catch(function () {});
      audioCtx = null;
    }
    sourceNode = null;
    delayNode = null;
    gainNode = null;
    preEnableGate.style.display = '';
    controlsArea.style.display = 'none';
    setDiagnostic('', 'Stopped. Confirm you\'re wearing headphones to start again.');
  }

  btnConfirmHeadphones.addEventListener('click', function () {
    preEnableGate.style.display = 'none';
    controlsArea.style.display = '';
    startMic(deviceSelect.value);
  });

  btnKillSwitch.addEventListener('click', killAll);

  deviceSelect.addEventListener('change', function () {
    if (audioCtx) {
      killAll();
      preEnableGate.style.display = 'none';
      controlsArea.style.display = '';
      startMic(deviceSelect.value);
    }
  });

  delaySlider.addEventListener('input', function () {
    var ms = parseFloat(delaySlider.value);
    delayValue.textContent = ms + ' ms';
    if (delayNode) delayNode.delayTime.value = ms / 1000;
  });

  window.addEventListener('pagehide', killAll);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') killAll();
  });

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic('error', '<strong>Your browser doesn’t support microphone access.</strong>');
    btnConfirmHeadphones.disabled = true;
  }
})();

(function () {
  'use strict';

  var video = document.getElementById('cameraVideo');
  var previewWrap = document.getElementById('cameraPreviewWrap');
  var placeholder = document.getElementById('cameraPlaceholder');
  var canvas = document.getElementById('analysisCanvas');
  var cueBox = document.getElementById('cueBox');
  var deviceSelect = document.getElementById('deviceSelect');
  var btnStart = document.getElementById('btnStartCamera');
  var btnStop = document.getElementById('btnStopCamera');
  var btnRunTest = document.getElementById('btnRunTest');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var statEstimate = document.getElementById('statEstimate');
  var statRawAvg = document.getElementById('statRawAvg');

  var TRIAL_COUNT = 6;
  var CHANGE_THRESHOLD = 30; // absolute brightness delta (either direction) counted as "the visitor moved"
  var TRIAL_TIMEOUT_MS = 2500;
  var AVG_VISUAL_REACTION_MS = 250; // typical average human visual reaction time, subtracted from the raw measurement

  var currentStream = null;
  var starting = false;
  var testing = false;

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

